(z0, kv, Σ, w1s, w2s, w3s) = ([0.3034779488568444, -0.629419375418374, 0.07677928744799473], [0.9856812720595798, 0.9822456469095393, 0.9663370628399683], [0.027921576704103473 -0.0027188771518694586 0.0010976855707291746; -0.0027188771518694586 0.035576779311823264 -0.0015958186602520468; 0.0010976855707291746 -0.0015958186602520468 0.06444208202855113], (m = -0.8095728876489761, s = 2.9904328434887386), (m = -1.8594780968043005, s = 2.435598925631213), (m = -3.815280149490534, s = 2.6845293048212304));
logistic(x) = 1 / (1 + exp(-x));

import Distributions.MvNormal
ΣD = MvNormal(zeros(3), Σ); # we've got the model param (kv, ΣD)
# Here simulation begins
zrnd = zeros(12,3);
zrnd[1, :] .= z0 # initial-time
for i = 2:size(zrnd, 1)
    tmpv = rand(ΣD)
    tmpv .+= (kv .* zrnd[i-1, :])
    zrnd[i, :] .= tmpv
end
